export function ApprovalNotification({
  requester = '{{requester}}',
  item = '{{item}}',
  status = '{{status}}',
  accent = '{{accent}}',
  timestamp = '{{timestamp}}',
  read = {{read}},
}) {
  const icon = { pending: '\u2026', approved: '\u2713', denied: '\u2715' }[status] ?? '\u2022';
  const iconColor = { pending: '#E8A020', approved: '#1a7a4c', denied: '#b0273e' }[status] ?? '#241430';
  const srOnly = { position: 'absolute', width: 1, height: 1, padding: 0, margin: -1, overflow: 'hidden', clip: 'rect(0,0,0,0)', whiteSpace: 'nowrap', border: 0 };
  return (
    <article style={{ display: 'flex', alignItems: 'flex-start', gap: 12, maxWidth: 420, padding: '14px 16px', background: '#FAF7F2', color: '#241430', borderLeft: `4px solid ${accent}`, borderRadius: 10, boxShadow: '0 6px 18px rgba(36,20,48,.12)', fontFamily: 'system-ui, sans-serif', fontSize: 14, position: 'relative' }}>
      <span aria-hidden='true' style={{ width: 22, height: 22, borderRadius: '50%', flexShrink: 0, background: '#24143014', display: 'grid', placeItems: 'center', fontWeight: 700, fontSize: 12, color: iconColor }}>{icon}</span>
      <div style={{ flex: 1 }}>
        <p style={{ margin: '0 0 4px' }}><strong>{requester}</strong> requested approval for <strong>{item}</strong></p>
        <p style={{ margin: '0 0 4px', fontSize: 12, color: '#241430b3' }}>Status: <span style={{ textTransform: 'capitalize', fontWeight: 600 }}>{status}</span></p>
        <time style={{ display: 'block', fontSize: 11, color: '#24143080' }} dateTime={timestamp}>{timestamp}</time>
      </div>
      {!read && (
        <>
          <span aria-hidden='true' style={{ position: 'absolute', top: 14, right: 14, width: 8, height: 8, borderRadius: '50%', background: '#b0273e' }} />
          <span style={srOnly}>Unread</span>
        </>
      )}
    </article>
  );
}
